/* =====================================================================
   LIVING SOBER WORDS (shared/sober-words.js), GWG BLD 837 and BLD 851
   Generated by patches/bld837/source/words.py in grounded-workshop:
   edit the data there and rebuild this file from it.

   window.GGSoberWords = {
     daily:     365 {id:'d001', text, stage?:[stage ids]}, one for each day of
                 the first year (d001 to d090 early days, GWG BLD 837; d091 to d365
                 growing sober, GWG BLD 851), then rotating (untagged items fit
                 every stage; a tagged item that misses the stage passes to the next)
     weekly:     52 {id:'w01', title, text}, reflections and practices
     monthly:    12 {id:'m01', title, today, past, future}, check-ins built on
                 80/10/10, one question each
     mantras:    60 {id:'mt01', text}, 2 to 10 words
     milestones: {d1, d3, d7, d14, d21, m1 to m11, y1 to y10, y} of {head, text};
                 y is the line for any year past ten, with {n} for the count
     love:       30 {id:'l01', text}, for Someone I Love
   }
   Rotation: pick by days since the sober date when it is set, otherwise by
   the day of the year (pick(list, n) wraps n around the list).
   Stage ids match GGLife.STAGES: change, early, growing, long, love.
   ===================================================================== */

(function () {
  var W = {
    daily: [
      {"id": "d001", "text": "Today you only need today. Drink a glass of water, eat a real meal, and get to bed early. That is a strong day.", "stage": ["change", "early"]},
      {"id": "d002", "text": "Tell one person you trust what you are doing. Something said out loud starts to grow roots."},
      {"id": "d003", "text": "Your body is busy healing. Rest when you can and keep water close. If you feel shaky, sweaty, or unwell, call your doctor today; early days can need a doctor's help.", "stage": ["change", "early"]},
      {"id": "d004", "text": "When a craving comes, set a timer for ten minutes. Drink water, walk, breathe. Cravings rise and fall like a wave, and you can ride this one."},
      {"id": "d005", "text": "Eat something every few hours today. Hunger can feel a lot like a craving, and a steady body makes a steadier mind.", "stage": ["change", "early"]},
      {"id": "d006", "text": "Step outside for ten minutes of daylight. Sunlight lifts your mood today and helps your sleep tonight."},
      {"id": "d007", "text": "Look back at the last seven days and name one moment you handled well. That moment is proof of what you can do."},
      {"id": "d008", "text": "Plan your hardest hour before it comes. Write down where you will be, who you will text, and what you will do instead."},
      {"id": "d009", "text": "Breathe in for four, hold for four, and breathe out for six. Do it five times. Your body listens to your breath."},
      {"id": "d010", "text": "Sleep may be uneven for a while. Keep the same bedtime, dim the lights an hour before, and let rest come in its own time.", "stage": ["early"]},
      {"id": "d011", "text": "Put three names in your phone under one label, like My People, so they are easy to find in a hard moment."},
      {"id": "d012", "text": "Put something good in your hand for the hour you used to drink: sparkling water with lime, hot tea, or tart cherry juice."},
      {"id": "d013", "text": "Feelings may come in big waves now. Name the feeling out loud. Naming it gives it a shape you can hold."},
      {"id": "d014", "text": "Think of who you were on day one, and thank that person for starting. Every day since has grown from that choice."},
      {"id": "d015", "text": "Move your body in a way you enjoy for twenty minutes. A walk counts. Movement burns off restless energy and lifts your mood."},
      {"id": "d016", "text": "Change one part of your old routine today: a new route home, a different chair, a new evening ritual. Small changes loosen old patterns."},
      {"id": "d017", "text": "Before you get out of bed, name one thing you are looking forward to today."},
      {"id": "d018", "text": "If you go somewhere with drinking today, bring your own drink, plan your way home, and let someone know you might call."},
      {"id": "d019", "text": "HALT is a quick check: Hungry, Angry, Lonely, Tired. When a craving hits, ask which one is true, and tend that first."},
      {"id": "d020", "text": "Your brain is rebuilding its sense of reward. Small pleasures may feel flat for a while, and they come back. Keep doing the good things.", "stage": ["early", "growing"]},
      {"id": "d021", "text": "You have already met mornings, evenings, and weekends sober. Each one you met makes the next one easier."},
      {"id": "d022", "text": "Write down why you started. Keep it on your phone or by your bed, and read it when the pull comes."},
      {"id": "d023", "text": "Make one meal today with whole foods: something green, a good protein, and real color on the plate. Your body is asking to be fed well."},
      {"id": "d024", "text": "Find your people. A meeting, a SMART Recovery group, a sober friend, a therapist, a faith community: try one this week and see how it fits."},
      {"id": "d025", "text": "If you feel restless at night, try a warm shower, a few gentle stretches, and slow breaths with long exhales before bed."},
      {"id": "d026", "text": "Picture yourself a year from now, waking up clear. What does that morning look like? Hold that picture while you live today."},
      {"id": "d027", "text": "Honesty keeps sobriety strong. Say one true thing today that you would usually keep inside."},
      {"id": "d028", "text": "Clear your space: pour out what is left, and fill the fridge with things that help you. Your home can work for you."},
      {"id": "d029", "text": "When the thought of just one comes, play the whole movie forward: the night, the morning, the next day. Then choose."},
      {"id": "d030", "text": "You are learning what you can do. Look at the days behind you and let yourself feel proud."},
      {"id": "d031", "text": "On the days your mind says you have this handled, keep your supports close anyway. Strong habits keep strong days."},
      {"id": "d032", "text": "Spend some time outdoors today, among trees if you can. Nature quiets a busy mind."},
      {"id": "d033", "text": "Boredom is common early on. Make a list of ten things you have wanted to try, and pick one for this week."},
      {"id": "d034", "text": "If prayer is part of your life, offer a short one this morning: help me today. Or take one quiet minute and set your intention for the day."},
      {"id": "d035", "text": "Drink a glass of water before your coffee. Small habits like this tell your body you are on its side."},
      {"id": "d036", "text": "Anger may show up now that the numbing is gone. Let it move through your body with a fast walk or a few push-ups, then decide what to say."},
      {"id": "d037", "text": "Ask someone how they are doing and really listen. Turning toward another person heals us, too."},
      {"id": "d038", "text": "Plan the weekend ahead today. Open, unplanned time can be the hardest time early on."},
      {"id": "d039", "text": "Think of one thing you have already gotten back: a morning, a memory, a conversation you will remember. That is yours to keep."},
      {"id": "d040", "text": "A hard feeling is a messenger. Sit with it for three slow breaths and ask what it needs."},
      {"id": "d041", "text": "Say it kindly and simply: “No thanks, I'm good.” You owe no one a reason."},
      {"id": "d042", "text": "Rest is part of recovery. A nap, an early night, or a slow afternoon counts as real work today."},
      {"id": "d043", "text": "Write down a craving when it comes: the time, the place, the feeling. Patterns show you where to plan."},
      {"id": "d044", "text": "Reach out while you are doing well. A quick text today builds the bridge you will cross on a harder day."},
      {"id": "d045", "text": "Imagine a sober trip or adventure you would love to take someday. Start a list of places."},
      {"id": "d046", "text": "Make breakfast part of your day. A morning meal with protein steadies your mood until lunch."},
      {"id": "d047", "text": "Learn one new sober way to celebrate good news: a favorite meal, a call to someone proud of you, a sunset walk."},
      {"id": "d048", "text": "Stretch for five minutes when you wake up. Start the day by meeting your body kindly."},
      {"id": "d049", "text": "If someone pushes you to drink, you can leave. Your sobriety comes first, and real friends will understand."},
      {"id": "d050", "text": "Watch your thoughts today like clouds passing. You can notice a thought and let it drift by."},
      {"id": "d051", "text": "Call someone you have lost touch with. Connection is rebuilt one call at a time."},
      {"id": "d052", "text": "Remember a hard moment from these weeks that you got through. You have proof now that you can do hard things."},
      {"id": "d053", "text": "Delete or mute one app, number, or feed that pulls you toward old habits."},
      {"id": "d054", "text": "Cook a meal for someone, or share one. Food shared at a table feeds more than the body."},
      {"id": "d055", "text": "If shame shows up about the past, speak to yourself the way you would speak to a friend: kindly, honestly, and with hope."},
      {"id": "d056", "text": "Notice your caffeine today. A lot of it can feel like anxiety. Swap the afternoon cup for water or herbal tea."},
      {"id": "d057", "text": "Learn your early warning signs: skipped meals, late nights, pulling away, a short temper. Notice one today and tend it."},
      {"id": "d058", "text": "Make your bed and tidy one corner. A small finished task tells your mind you are capable."},
      {"id": "d059", "text": "Write one sentence about who you are becoming. Read it again tomorrow morning."},
      {"id": "d060", "text": "Look how much life has fit into these sober days. Every one of them was yours."},
      {"id": "d061", "text": "Find one thing that makes you laugh today. Joy belongs in sobriety, too."},
      {"id": "d062", "text": "Look for one way your body is thanking you: clearer eyes, steadier sleep, more energy, a calmer stomach."},
      {"id": "d063", "text": "If you feel tempted to test yourself, choose to protect yourself instead. Strength is knowing what you need."},
      {"id": "d064", "text": "Spend twenty minutes in a place that calms you: a park, a library, a quiet room, a lakeshore."},
      {"id": "d065", "text": "Ask for help with one thing today, even a small thing. Asking is a skill, and it grows with practice."},
      {"id": "d066", "text": "Try a slow body scan tonight: from your feet to your head, notice each part and let it soften."},
      {"id": "d067", "text": "The feelings you used to drink over are still here, and now you get to heal them. Healing is real, one honest day at a time."},
      {"id": "d068", "text": "Keep your hands busy in the hard hour: cook, draw, fix something, garden, or play an instrument."},
      {"id": "d069", "text": "Tell someone what is going well. Good news shared grows."},
      {"id": "d070", "text": "If a slip ever happens, it is a moment, never a verdict. Reach out the same day, tend your body, and begin again."},
      {"id": "d071", "text": "Look at your calendar for the coming week and mark the hard spots. Put a plan next to each one."},
      {"id": "d072", "text": "Think of someone you want to be there for in the years ahead. Your sober days today are building that."},
      {"id": "d073", "text": "Keep your morning simple: water, daylight, a few slow breaths, and a plan for the day."},
      {"id": "d074", "text": "Sugar cravings are common early on. Reach for fruit, nuts, or a real meal, and drink water. Your body is finding its balance.", "stage": ["early"]},
      {"id": "d075", "text": "Remember the first morning you woke up clear. Hold onto that feeling; it is a gift you gave yourself."},
      {"id": "d076", "text": "Every kind of help counts: a group, a mentor, a doctor, a therapist, a coach, a faith leader, a friend. Use the ones that help you."},
      {"id": "d077", "text": "Do one thing today your future self will thank you for: a walk, a bill paid, a call made, an early night."},
      {"id": "d078", "text": "Loneliness is a signal to reach toward people. Go where people are today: a meeting, a gym, a class, a place of worship, a coffee shop."},
      {"id": "d079", "text": "Practice gratitude out loud. Tell someone one thing you appreciate about them."},
      {"id": "d080", "text": "Your story is still being written, and the chapters ahead hold good things. Today is one good page."},
      {"id": "d081", "text": "If you feel stuck, change your setting. A walk around the block can change the whole hour."},
      {"id": "d082", "text": "Let today be ordinary. Ordinary days, lived clear, are the ground a sober life grows on."},
      {"id": "d083", "text": "Think about how you would like to mark ninety days: a favorite meal, a hike, time with people who are proud of you. Plan it."},
      {"id": "d084", "text": "Put on music you love and really listen, with nothing else going on."},
      {"id": "d085", "text": "Think of a skill or dream you set aside long ago. Your clear mind can pick it back up."},
      {"id": "d086", "text": "Keep the basics strong: sleep, water, whole food, movement, and people. They are simple, and they work."},
      {"id": "d087", "text": "Look back at day one. Name three ways you have grown since then."},
      {"id": "d088", "text": "Help someone today in a small way: hold a door, send a note, give an hour. Service keeps us grounded."},
      {"id": "d089", "text": "Write down one hope for the next ninety days: a habit, a relationship, or a dream to begin."},
      {"id": "d090", "text": "Live this day fully, the same way you lived the others: one day, clear and present, is how a sober life is built."},
      {"id": "d091", "text": "Ninety days are behind you, and a new season begins. Keep the habits that carried you here, and let them grow with you.", "stage": ["early", "growing", "long"]},
      {"id": "d092", "text": "Growing sober is about building a life you want to wake up to. Name one thing you would like to add to your days this month."},
      {"id": "d093", "text": "Check your basics this morning: water, a real breakfast, daylight, and a plan for the hard hour. Strong basics make room for everything else."},
      {"id": "d094", "text": "Who are you becoming now that your mornings are clear? Write three words that describe that person, and live one of them today.", "stage": ["early", "growing", "long"]},
      {"id": "d095", "text": "Try a new sober activity this week: a pottery class, a climbing gym, a choir, a trail that is new to you. New interests help a new life take shape."},
      {"id": "d096", "text": "Your leaves are your body. Give them a good day: a long walk, a colorful lunch, and lights out at a steady time."},
      {"id": "d097", "text": "Sit with a friend who lives well and ask what keeps them steady. Healthy people are glad to share what works."},
      {"id": "d098", "text": "Remember a gathering you once dreaded and walked through sober. Let that memory remind you how much you have learned.", "stage": ["early", "growing", "long"]},
      {"id": "d099", "text": "Find a rhythm for your week: a day to move hard, a day to rest, a day to see people, a day outdoors. Rhythm holds a life steady."},
      {"id": "d100", "text": "One hundred days. Take a slow breath and let that number land. Every one of those days was a choice you made for yourself.", "stage": ["early", "growing", "long"]},
      {"id": "d101", "text": "Celebrate one hundred days in a healthy way that feels like you: a favorite meal, a sunrise hike, a call to someone who believes in you.", "stage": ["early", "growing", "long"]},
      {"id": "d102", "text": "Look at the people you spend the most time with. Lean toward the ones who are healthy and thriving; over time, their habits become yours."},
      {"id": "d103", "text": "Choose a bedtime and protect it this week. Deep sleep is where your mind sorts the day and your body repairs."},
      {"id": "d104", "text": "If an old craving visits after a long quiet stretch, greet it calmly. It is an old echo, and you know how to ride it now.", "stage": ["early", "growing", "long"]},
      {"id": "d105", "text": "Cook something new tonight with whole foods and plenty of color. Learning to feed yourself well is a gift that lasts."},
      {"id": "d106", "text": "Your bark is your mind: how you calm down and heal over. Practice one calming skill today while things are easy, so it is ready when you need it."},
      {"id": "d107", "text": "Picture the season ahead lived sober and full. What would you love to do with it? Write one plan down."},
      {"id": "d108", "text": "Spend time with someone older who has lived well. Ask what they have learned about a good life."},
      {"id": "d109", "text": "Keep a water bottle where you can see it all day. Steady water keeps your energy and your mood more even."},
      {"id": "d110", "text": "Notice how you talk to yourself today. Speak to yourself like someone you love who is doing well."},
      {"id": "d111", "text": "Choose one evening this week to be unplugged from dinner to bed. Read, walk, talk, stretch, and see how you sleep."},
      {"id": "d112", "text": "Think of someone who stood by you in the early days. Send them a short thank you today.", "stage": ["early", "growing", "long"]},
      {"id": "d113", "text": "Sobriety gives you back time. Pick one hour this week and spend it on something that makes you feel alive."},
      {"id": "d114", "text": "Healing is real, and it often comes in layers. When an old hurt rises, let it be a sign that you are ready to tend it."},
      {"id": "d115", "text": "Try a cool rinse at the end of your shower, or a brisk walk on a crisp morning. A little challenge wakes up the body and the mind."},
      {"id": "d116", "text": "Make your home a place you love: fresh air, a plant, good light, a clear table. Your surroundings shape your days."},
      {"id": "d117", "text": "Start a page called Someday. Write down every place, skill, and adventure you would love, and add to it all year."},
      {"id": "d118", "text": "When someone asks how you are, try telling the truth. Real answers build real friendships."},
      {"id": "d119", "text": "Your branches are your people. Water one friendship today with a call, a visit, or a walk together."},
      {"id": "d120", "text": "Four months of practice is building something steady inside you. Keep showing up for the small things; they add up to a strong life.", "stage": ["early", "growing", "long"]},
      {"id": "d121", "text": "Learn the difference between rest and escape. Rest fills you back up; ask yourself which one you are choosing tonight."},
      {"id": "d122", "text": "Take your movement outside today. Walk, bike, or run where you can see sky and trees."},
      {"id": "d123", "text": "Notice what lights you up. Joy is a clue to the life you are here to build."},
      {"id": "d124", "text": "Imagine your birthday a year from now, celebrated sober and surrounded by good people. Who is there? Reach out to one of them this week."},
      {"id": "d125", "text": "Healthy boundaries keep your peace. Practice one kind, clear sentence today: “That works for me,” or “I'll pass on that one.”"},
      {"id": "d126", "text": "Eat slowly at one meal today. Taste each bite, set your fork down between bites, and notice when you are full."},
      {"id": "d127", "text": "Shame shrinks when it is spoken to someone safe. If something heavy is still hidden, choose one trusted person to tell."},
      {"id": "d128", "text": "Try a breath practice before bed: breathe in through your nose, and let a long, slow breath out through your mouth. Ten rounds, then sleep."},
      {"id": "d129", "text": "Look back over your sober months and name a fear that turned out smaller than you expected.", "stage": ["early", "growing", "long"]},
      {"id": "d130", "text": "Join something that gathers every week: a running group, a class, a volunteer shift, a choir. Showing up each week builds belonging."},
      {"id": "d131", "text": "Your trunk is your meaning, the larger story you live inside. Ask yourself today what your sober story is about."},
      {"id": "d132", "text": "Mend one small thing at home today: a squeaky door, a loose button, a cluttered shelf. Mending things teaches the hands patience."},
      {"id": "d133", "text": "Feelings you once numbed may arrive with new force. Let them come, write them down, and talk them through with someone you trust."},
      {"id": "d134", "text": "Plan a sober evening and host it: good food, music, games, sparkling drinks. You get to set the tone for a joyful night."},
      {"id": "d135", "text": "Notice one person in your life who drains your peace. Give that relationship a little more space, and give your energy to people who lift you."},
      {"id": "d136", "text": "Go to bed and wake up at the same time all week, weekends included. A steady clock makes steady days."},
      {"id": "d137", "text": "Take a walk and leave your phone at home. Let your thoughts wander and your senses take in the day."},
      {"id": "d138", "text": "Write down three things you hope your sober life makes possible in the next five years. Keep the list where you will see it."},
      {"id": "d139", "text": "Practice saying yes to good things: an invitation to hike, a class, a new friend. A full life grows from many small yeses."},
      {"id": "d140", "text": "Anger can carry useful information. When it comes, pause, breathe, and ask what boundary or value it is pointing to."},
      {"id": "d141", "text": "Fill your plate today with real food: vegetables, fruit, beans, eggs, fish, nuts, whole grains. Food that grows from the earth helps you grow, too."},
      {"id": "d142", "text": "Spend ten minutes in silence this morning. Sit, breathe, and let your roots settle into what holds you steady."},
      {"id": "d143", "text": "If you are rebuilding trust with someone, keep small promises well. Trust returns through steady, ordinary days."},
      {"id": "d144", "text": "Find one thing you can learn this month: a recipe, a song on guitar, a stretch routine, a new trail. Learning keeps a mind bright."},
      {"id": "d145", "text": "Think of a younger you who was hurting. Send that person a little kindness today; you are the one who gets to help them heal."},
      {"id": "d146", "text": "Move hard enough today to breathe deeply: a hill, a set of stairs, a fast swim. A tired body sleeps well and worries less."},
      {"id": "d147", "text": "Check in with your body at noon: shoulders, jaw, belly, breath. Soften one place and drink a glass of water."},
      {"id": "d148", "text": "Sober friendships grow through shared doing. Invite someone to cook, hike, build, or play a sport with you."},
      {"id": "d149", "text": "When life gets busy, keep your anchors: a morning rhythm, real meals, movement, sleep, and people. These carry you through full seasons."},
      {"id": "d150", "text": "One hundred fifty days of living clear. Let your hope for the coming months grow as big as the life you are building.", "stage": ["early", "growing", "long"]},
      {"id": "d151", "text": "Look for wonder today: a bird, a cloud, a child's laugh, the smell of rain. Wonder is a quiet kind of joy."},
      {"id": "d152", "text": "Learn your own early signs of stress: a tight chest, short words, skipped meals. Catch one today and tend it with a pause and a breath."},
      {"id": "d153", "text": "Ask someone you admire to share their morning routine. Borrow one piece and try it this week."},
      {"id": "d154", "text": "Let yourself have fun in a simple way: a game, a swim, a dance in the kitchen. Playfulness is part of healing."},
      {"id": "d155", "text": "Old places and old friends can pull at you. Choose the places and people that fit the life you are growing now."},
      {"id": "d156", "text": "Write a letter to someone who hurt you, just for you to keep. Say it all on paper, then decide what to hold and what to release."},
      {"id": "d157", "text": "Get outside at sunset tonight. Watch the light change and let the day close gently."},
      {"id": "d158", "text": "Remember the first sober weekend you truly enjoyed. Plan another one like it.", "stage": ["early", "growing", "long"]},
      {"id": "d159", "text": "Choose one healthy friend to check in with each week, and ask them to check in with you. Steady connection keeps you both strong."},
      {"id": "d160", "text": "Your body may be getting stronger. Give it a new challenge: a longer walk, a few more push-ups, a yoga class, a swim."},
      {"id": "d161", "text": "If a holiday or anniversary is coming, plan it now: where you will be, who will be with you, and how you will celebrate sober."},
      {"id": "d162", "text": "Notice when you reach for something to change how you feel: food, scrolling, shopping, work. Pause, breathe, and ask what the feeling needs."},
      {"id": "d163", "text": "What kind of friend, partner, parent, or neighbor do you want to be in a year? Do one thing today that looks like that person."},
      {"id": "d164", "text": "Drink water first thing, then step into the daylight. Two small acts set a whole day's direction."},
      {"id": "d165", "text": "Healing old hurts often goes better with help. A therapist or a trusted guide can walk with you through the deep parts."},
      {"id": "d166", "text": "Clear one thing that drains you from your calendar, and put in one thing that fills you."},
      {"id": "d167", "text": "Sing, hum, or play music today. Sound and rhythm calm the body and lift the heart."},
      {"id": "d168", "text": "Eat breakfast at a table, slowly, with someone if you can. Shared mornings build warm days."},
      {"id": "d169", "text": "Practice forgiveness in small ways: a driver who cut you off, a friend who forgot, yourself for a mistake. Each small one makes the big ones lighter."},
      {"id": "d170", "text": "Look at a photo from before you started living sober. Notice how far you have come, and thank yourself.", "stage": ["early", "growing", "long"]},
      {"id": "d171", "text": "Hike, garden, or sit by water today. Time outdoors restores what a busy week wears down."},
      {"id": "d172", "text": "When you feel lonely, reach out first. One text now can turn into a walk later."},
      {"id": "d173", "text": "Pick one healthy habit and do it every day this week: stretching, a walk after dinner, or lights out by ten."},
      {"id": "d174", "text": "Speak well of yourself today. Name one strength out loud that has grown during your sober months.", "stage": ["early", "growing", "long"]},
      {"id": "d175", "text": "Make one healthy swap today: water for soda, fruit for candy, a walk for the scroll. Small swaps make a big difference over months."},
      {"id": "d176", "text": "Begin planning something you can do best with a clear mind: a race, a trip, a course, a project. Put the first step on your calendar."},
      {"id": "d177", "text": "Time alone can be peaceful and healthy. Make your solo time rich: a good book, a long walk, a meal you cook just for you."},
      {"id": "d178", "text": "If an argument comes up at home, take a walk first and talk second. Calm words travel further."},
      {"id": "d179", "text": "Laugh with someone today. Shared laughter is one of the fastest ways people grow close."},
      {"id": "d180", "text": "Look around at the healthy life that is filling in: the routines, the people, the mornings. Keep tending it."},
      {"id": "d181", "text": "About half a year. Look back over these months with gentle eyes and name what you are proudest of.", "stage": ["early", "growing", "long"]},
      {"id": "d182", "text": "Set an intention for the next six months: one habit to deepen, one relationship to grow, one dream to begin."},
      {"id": "d183", "text": "Mark your half year with something healthy and joyful: a hike to a view, a dinner with people who love you, a toast with sparkling water.", "stage": ["early", "growing", "long"]},
      {"id": "d184", "text": "Your roots are what you are anchored in. Spend a few quiet minutes today with whatever holds you steady."},
      {"id": "d185", "text": "Notice the gifts sobriety has brought you, small and large. Say one out loud to someone today."},
      {"id": "d186", "text": "Think about giving back in a way that fits you: a volunteer shift, mentoring, coaching a team, helping a neighbor. Service grows purpose."},
      {"id": "d187", "text": "Keep stretching your comfort zone a little at a time. Try one thing this week that feels slightly bold."},
      {"id": "d188", "text": "Sleep is still medicine. Keep your room dark, cool, and quiet, and give yourself a full night in bed."},
      {"id": "d189", "text": "Ask a friend to try a new healthy recipe with you. Cooking together feeds the body and the friendship."},
      {"id": "d190", "text": "Old memories may surface as you heal. Write them down, breathe through them, and bring the heavy ones to someone trained to help."},
      {"id": "d191", "text": "Think of the steady person growing in you. How do they spend an ordinary Tuesday? Live a piece of that day today."},
      {"id": "d192", "text": "If it fits you, spend time with someone newer on the path. A listening ear can mean the world to someone just starting.", "stage": ["growing", "long"]},
      {"id": "d193", "text": "Take a slow walk in a park or forest and breathe in the air. Trees have a way of quieting a busy mind."},
      {"id": "d194", "text": "Check your words today. Say what you want, what you will do, and who you are becoming."},
      {"id": "d195", "text": "If a new habit starts taking the old one's place, be honest with yourself about it. Tend the feeling underneath, and keep your life in balance."},
      {"id": "d196", "text": "Plan your week on Sunday: meals, movement, people, rest. A planned week leaves room for joy."},
      {"id": "d197", "text": "Name one relationship that is stronger now than it was six months ago. Tell that person what it means to you.", "stage": ["early", "growing", "long"]},
      {"id": "d198", "text": "Your mind grows clearer with time. Use it today to read something that feeds you."},
      {"id": "d199", "text": "Choose a healthy comfort for a hard day: a hot bath, a favorite tea, an early night, a call to a friend."},
      {"id": "d200", "text": "Two hundred days. Each one is a ring of growth in your tree. Pause today and honor them.", "stage": ["early", "growing", "long"]},
      {"id": "d201", "text": "Be a good friend to your body today: water, movement, whole food, rest, and fresh air."},
      {"id": "d202", "text": "Notice someone who could use encouragement, and give it warmly and simply."},
      {"id": "d203", "text": "When you make a mistake, own it quickly and kindly. Quick repairs keep relationships healthy."},
      {"id": "d204", "text": "Explore a new place nearby this weekend: a trail, a lake, a town, a museum. Curiosity keeps a sober life fresh."},
      {"id": "d205", "text": "Write down what you want your sober years to give the people you love. Let that be part of your reason today."},
      {"id": "d206", "text": "Try gentle stretching or yoga tonight. Ten minutes of slow movement eases the body into rest."},
      {"id": "d207", "text": "If you feel flat or restless, change something small: a new walking route, a new recipe, a new friend to call."},
      {"id": "d208", "text": "Gratitude grows with use. Write three good things from today before you sleep."},
      {"id": "d209", "text": "Spend an hour helping someone with something practical: moving a couch, raking leaves, fixing a bike. Useful hands lift a heavy heart."},
      {"id": "d210", "text": "Healthy, thriving people are all around you. Look for them at the trailhead, the gym, the garden, the volunteer table."},
      {"id": "d211", "text": "If you have a partner, plan a sober date: a picnic, a hike, a cooking class, a concert. Clear evenings make memories you keep."},
      {"id": "d212", "text": "Recall a hard day these past months that you met with grace. That steadiness belongs to you.", "stage": ["early", "growing", "long"]},
      {"id": "d213", "text": "Take a moment to breathe before you answer a hard message. A pause gives your wisest self time to speak."},
      {"id": "d214", "text": "Bring more color to your plate this week: greens, berries, beans, squash, peppers. Color is a sign of good nourishment."},
      {"id": "d215", "text": "Find a way to be useful to your community: a cleanup day, a food shelf, a youth team. Belonging grows when we serve together."},
      {"id": "d216", "text": "Imagine someone telling your story ten years from now. What would you love them to say? Live a line of it today."},
      {"id": "d217", "text": "Rest with a clear conscience today. A slow afternoon is part of a healthy life."},
      {"id": "d218", "text": "Notice what you are grateful for in your own body: legs that walk, lungs that breathe, a heart that keeps going."},
      {"id": "d219", "text": "Have a real conversation today, face to face, with your phone put away."},
      {"id": "d220", "text": "Keep learning about yourself. Ask what helps you most when you feel low, and build more of it into your week."},
      {"id": "d221", "text": "Spend a little time with children or elders this week if you can. Both have a way of grounding us in what matters."},
      {"id": "d222", "text": "Choose a word for this season of your life, like steady, open, or brave. Let it guide one choice today."},
      {"id": "d223", "text": "Think of a skill you have built these months, like asking for help or riding out a craving. Name it, and own it.", "stage": ["early", "growing", "long"]},
      {"id": "d224", "text": "If you are invited somewhere uncertain, decide ahead how long you will stay and how you will leave. A plan lets you enjoy the evening."},
      {"id": "d225", "text": "Give your spirit some room today: music, art, prayer, nature, or quiet. Whatever lifts your heart is worth the time."},
      {"id": "d226", "text": "Notice how sobriety has changed your mornings. Use that clear time for something that matters to you.", "stage": ["early", "growing", "long"]},
      {"id": "d227", "text": "Get your heart rate up for twenty minutes today. A strong heart supports a steady mood."},
      {"id": "d228", "text": "Let someone help you today, even with something small. Receiving is part of real friendship."},
      {"id": "d229", "text": "Pick one goal for the next three months that excites you. Tell someone, and ask them to cheer you on."},
      {"id": "d230", "text": "Notice the stories you tell about your past. Tell them with honesty and with hope, because you are still growing."},
      {"id": "d231", "text": "Prepare a few healthy meals ahead this week. A full fridge makes good choices easy on busy days."},
      {"id": "d232", "text": "Walk with a friend and talk about what you are learning. Sharing your growth helps it take root."},
      {"id": "d233", "text": "Sit outside with your morning tea or coffee and watch the day begin. Slow starts make steady days."},
      {"id": "d234", "text": "When someone close to you is struggling, offer presence first: sit with them, listen, and ask what would help."},
      {"id": "d235", "text": "Let go of one grudge today, even a small one. Carrying less makes room for peace."},
      {"id": "d236", "text": "Tend your bark today: when stress rises, slow your breath, name the feeling, and choose your next step."},
      {"id": "d237", "text": "Think of a time you chose your sobriety over an easy yes. That choice shaped who you are.", "stage": ["early", "growing", "long"]},
      {"id": "d238", "text": "Look for a way to share what has helped you, in your own words, with someone who asks.", "stage": ["early", "growing", "long"]},
      {"id": "d239", "text": "Spend time in water if you can: a swim, a lake, a long bath. Water calms and restores."},
      {"id": "d240", "text": "Your future is opening up. Name one door you would love to walk through, and take one step toward it."},
      {"id": "d241", "text": "Sobriety is becoming part of who you are. Notice where it shows: in your choices, your words, and your mornings.", "stage": ["early", "growing", "long"]},
      {"id": "d242", "text": "Plan a sober adventure for the coming season: a camping trip, a long ride, a mountain, a coastline."},
      {"id": "d243", "text": "Keep your circle healthy. Spend more time with people who leave you feeling stronger."},
      {"id": "d244", "text": "Feed your mind something good today: a book, a lecture, a long talk with someone wise."},
      {"id": "d245", "text": "Breathe deeply three times before each meal today. Calm eating helps your body take in the good."},
      {"id": "d246", "text": "Sketch a picture or a map of the life you are growing toward: home, people, work, play. Keep it where you will see it."},
      {"id": "d247", "text": "If old ways start to pull during a hard season, lean harder on what works: sleep, food, movement, people, and quiet."},
      {"id": "d248", "text": "Welcome solitude when it comes. Time alone to think, walk, and rest can be deeply healthy."},
      {"id": "d249", "text": "Invite a friend to try something new with you: a climbing wall, a dance class, a cooking night. Shared firsts make strong bonds."},
      {"id": "d250", "text": "Two hundred fifty days. Look back at the path and see how much ground it covers. You walked every step.", "stage": ["early", "growing", "long"]},
      {"id": "d251", "text": "Notice where you can be generous today: with time, attention, patience, or a kind word."},
      {"id": "d252", "text": "Get daylight early, move during the day, and dim the lights at night. Your body loves a clear rhythm."},
      {"id": "d253", "text": "Healing deep hurts can take seasons. Be patient with yourself and keep showing up for the work."},
      {"id": "d254", "text": "Spend time with someone who has many years of healthy living. Their steady life is a picture of where yours is going."},
      {"id": "d255", "text": "Picture yourself five years from now, healthy and thriving. Look at the people around you today, and walk with the ones headed toward that same life."},
      {"id": "d256", "text": "Clear out one corner of your life this week: a closet, an inbox, an old commitment. Clear space invites new growth."},
      {"id": "d257", "text": "Celebrate someone else's win today. Joy shared grows bigger."},
      {"id": "d258", "text": "Learn one new skill for your body: a stretch for your back, a breathing pattern, a good squat. Your body is worth learning."},
      {"id": "d259", "text": "If it fits you, let your faith or your deepest values speak into a decision today. Roots hold best when we lean on them."},
      {"id": "d260", "text": "When you feel proud, let yourself feel it fully. Healthy pride fuels the next good choice."},
      {"id": "d261", "text": "Go to a place that feels like peace and stay a while: a garden, a trail, a bench by the water."},
      {"id": "d262", "text": "Notice how you handle conflict now. Calm, honest words are a sign of real growth.", "stage": ["early", "growing", "long"]},
      {"id": "d263", "text": "Think of one person who believed in you before you believed in yourself. Thank them, in person or in your heart."},
      {"id": "d264", "text": "Choose foods today that leave you feeling strong and clear an hour later. Your body will tell you what serves it."},
      {"id": "d265", "text": "Build in one small adventure this week: a sunrise, a new trail, a dish from another part of the world made at home."},
      {"id": "d266", "text": "Repair takes time. If there is someone you hope to reconcile with, write down what you would like them to know, and wait for the right moment."},
      {"id": "d267", "text": "Your branches grow stronger when you show up. Go to the birthday, the game, the dinner, and be fully there."},
      {"id": "d268", "text": "Name one way you would love to help others in the years ahead. Let today's choices build toward it."},
      {"id": "d269", "text": "Keep your evenings calm: a light dinner, a walk, warm light, and a book. Calm evenings lead to deep sleep."},
      {"id": "d270", "text": "When you think ahead today, picture things going well. Hopeful pictures guide hopeful choices."},
      {"id": "d271", "text": "Ask someone you trust what they see growing in you. Let their words encourage you."},
      {"id": "d272", "text": "Drink water through the afternoon slump, and take a short walk in place of a sugary snack. Your energy will thank you."},
      {"id": "d273", "text": "About nine months now. Write down three ways your ordinary days look different from your first week.", "stage": ["early", "growing", "long"]},
      {"id": "d274", "text": "Teach someone something you have learned: a recipe, a stretch, a way to calm down. Teaching deepens your own roots."},
      {"id": "d275", "text": "Let today hold one slow pleasure: a long walk, a warm meal, a good conversation."},
      {"id": "d276", "text": "When old guilt shows up, ask what it wants you to learn, then set it down. You are allowed to move forward."},
      {"id": "d277", "text": "Find a healthy group that does something you love, and go twice. The second visit is where belonging begins."},
      {"id": "d278", "text": "Keep your phone out of the bedroom tonight. Let the last hour of your day be calm and unplugged."},
      {"id": "d279", "text": "Think of a place you would love to see in the next year. Start saving and planning for it today."},
      {"id": "d280", "text": "Honor your limits today. Passing on one thing makes room for rest."},
      {"id": "d281", "text": "Look at your week and make sure each day has movement, real food, rest, and a moment with people."},
      {"id": "d282", "text": "Spend a few minutes with the sky tonight: the stars, the moon, the clouds. Big skies make worries feel smaller."},
      {"id": "d283", "text": "Notice how your relationships have changed. Some have grown, some have faded; let each one be what it is.", "stage": ["early", "growing", "long"]},
      {"id": "d284", "text": "Do one thing today simply because it is good for your spirit."},
      {"id": "d285", "text": "Remember how heavy the first weeks felt, and notice how much lighter you carry yourself now.", "stage": ["early", "growing", "long"]},
      {"id": "d286", "text": "Practice listening fully today: eyes up, phone down, curious questions. People feel loved when they feel heard."},
      {"id": "d287", "text": "If a hard memory returns, ground yourself: feet on the floor, five things you can see, a slow breath. Then reach out if you need to."},
      {"id": "d288", "text": "Make one meal this week a celebration of good food with people you love."},
      {"id": "d289", "text": "Write for ten minutes about what freedom feels like in your sober life. Read it back on a hard day.", "stage": ["early", "growing", "long"]},
      {"id": "d290", "text": "Plant something today: a seed, a bulb, a tree. Watch it grow alongside you this year."},
      {"id": "d291", "text": "Let your work reflect your values. Do one task today with your full attention and your best effort."},
      {"id": "d292", "text": "Healthy solitude restores you. If time alone starts to feel heavy, reach out today to one healthy person and make a plan to meet."},
      {"id": "d293", "text": "Take the stairs, park farther away, walk while you talk on the phone. Movement woven into the day adds up."},
      {"id": "d294", "text": "Send a kind wish to someone today, in your own words, quietly or out loud."},
      {"id": "d295", "text": "Look back at a promise you made to yourself early on and kept. You are someone who keeps promises.", "stage": ["early", "growing", "long"]},
      {"id": "d296", "text": "Let your home hold healthy things: good food in the fridge, sparkling water, a full bookshelf, walking shoes by the door."},
      {"id": "d297", "text": "Bring kindness to a hard conversation today. Start with what you value about the other person."},
      {"id": "d298", "text": "Choose a project that will take months: a garden, a quilt, a course, a training plan. Long projects grow patience and hope."},
      {"id": "d299", "text": "Step outside after dinner for a short walk. It helps your body settle and your mind slow down."},
      {"id": "d300", "text": "Three hundred days. Let that number remind you how strong steady choices are.", "stage": ["early", "growing", "long"]},
      {"id": "d301", "text": "As your year draws near, keep living today fully. The year is made of days like this one.", "stage": ["early", "growing", "long"]},
      {"id": "d302", "text": "Notice the people who have grown alongside you. Tell one of them what their friendship has meant."},
      {"id": "d303", "text": "Try a new form of movement this month: a dance class, a paddle, a martial art, a long bike ride."},
      {"id": "d304", "text": "Begin to imagine how you would like to mark one year: a place, a meal, the people, a ritual that means something to you.", "stage": ["early", "growing", "long"]},
      {"id": "d305", "text": "Healing keeps going past every milestone. Keep tending the deep places with patience, and with help when you need it."},
      {"id": "d306", "text": "Cook a dish from your family's past, made the healthy way. Food can carry memory and love."},
      {"id": "d307", "text": "Notice your breath right now. Slow it, deepen it, and let your shoulders drop."},
      {"id": "d308", "text": "When someone newer asks how you did it, tell them what helped you, simply and honestly.", "stage": ["early", "growing", "long"]},
      {"id": "d309", "text": "Make room for quiet each day: five minutes alone with your thoughts, your breath, or a prayer if that is yours."},
      {"id": "d310", "text": "Book a visit with your doctor if one is due. A clear picture of your health helps you keep growing well."},
      {"id": "d311", "text": "Choose to be around people who laugh easily and live well. Their joy is contagious."},
      {"id": "d312", "text": "Think of a moment this year when you surprised yourself with your strength. Hold it close.", "stage": ["early", "growing", "long"]},
      {"id": "d313", "text": "Let today be gentle if you are tired. Rest is how strength rebuilds."},
      {"id": "d314", "text": "Give an afternoon to service this month. Choose something that uses your gifts."},
      {"id": "d315", "text": "Notice how your senses have come alive: the taste of food, the colors outside, the sound of rain. Enjoy them today.", "stage": ["early", "growing", "long"]},
      {"id": "d316", "text": "Write a short list of hopes for your second year. Let them be bold and kind.", "stage": ["early", "growing", "long"]},
      {"id": "d317", "text": "Hold your boundaries with warmth today. You can be kind and clear at the same time."},
      {"id": "d318", "text": "Spend time near water or among trees this week. Nature keeps reminding us that growth takes seasons."},
      {"id": "d319", "text": "Eat a big, colorful salad or a warm bowl of vegetables today. Nourishing food is a daily act of respect for yourself."},
      {"id": "d320", "text": "If the holidays or a hard date is ahead, make your plan early and share it with your good people."},
      {"id": "d321", "text": "Take a picture today of something that stands for your sober life: a trail, a table, a sunrise. Keep a gallery of the good."},
      {"id": "d322", "text": "Remember someone who helped you this year in a small way that mattered. Pass that kindness on today."},
      {"id": "d323", "text": "Notice how you calm yourself now. Each calm return is your bark healing over strong."},
      {"id": "d324", "text": "Invite someone over for a meal and good conversation. A shared table is one of life's best gifts."},
      {"id": "d325", "text": "Imagine walking alongside someone else in their first days someday. Your growth now is preparing you for it.", "stage": ["growing", "long"]},
      {"id": "d326", "text": "Get moving early today. A morning walk or workout sets a strong tone for everything else."},
      {"id": "d327", "text": "Keep your routines when life is going well. Good seasons are a great time to deepen good habits."},
      {"id": "d328", "text": "Write down five things that bring you peace. Do one of them today."},
      {"id": "d329", "text": "Notice the ways you are trusted now: with keys, with secrets, with children, with work. Trust is a sign of steady days.", "stage": ["early", "growing", "long"]},
      {"id": "d330", "text": "Let yourself dream about the year ahead. Your clear mind is a powerful place to plan from."},
      {"id": "d331", "text": "Spend time with your branches today: call family, write to a friend, plan a get-together."},
      {"id": "d332", "text": "Choose a sober ritual for your evenings: tea, a walk, a page of writing, lights low. Rituals tell your body it is safe to rest."},
      {"id": "d333", "text": "If you had a slip or a hard stretch this year, look back and notice what it taught you. Every return to the path counts.", "stage": ["early", "growing", "long"]},
      {"id": "d334", "text": "Keep your body moving every day this week, even for ten minutes. Steady practice builds strength."},
      {"id": "d335", "text": "Invite the people you would like around you for your one-year day, or plan a quiet solo celebration if that suits you better.", "stage": ["early", "growing", "long"]},
      {"id": "d336", "text": "Notice the healthy people you are drawing closer to. You are becoming one of them for someone else.", "stage": ["early", "growing", "long"]},
      {"id": "d337", "text": "Bring something festive to your next gathering: a sparkling drink to share, a dish you love. Hosting healthy joy is a gift."},
      {"id": "d338", "text": "When stress rises this week, take a walk before you decide anything. Movement clears the mind."},
      {"id": "d339", "text": "Read something you wrote in your early days, if you kept it. Notice how your voice has grown.", "stage": ["early", "growing", "long"]},
      {"id": "d340", "text": "Offer thanks before a meal today, in whatever way fits you. Gratitude makes food taste better."},
      {"id": "d341", "text": "Spend one evening fully unplugged with people you love. Talk, play, cook, walk."},
      {"id": "d342", "text": "Think of one way you would like to give back in your second year. Write it down and tell someone.", "stage": ["early", "growing", "long"]},
      {"id": "d343", "text": "Notice what still feels tender, and treat it gently. Healing has its own pace."},
      {"id": "d344", "text": "Step outside in the cold or the heat, dressed for it, and feel your body adjust. You are stronger than you think."},
      {"id": "d345", "text": "Say yes to one healthy invitation this week, even if part of you would rather stay home."},
      {"id": "d346", "text": "Sleep in a dark, cool room tonight, and wake with daylight. Your body loves the simple rhythm of the sun."},
      {"id": "d347", "text": "Name the hardest day of your sober year so far, and the help that got you through it. Thank that help.", "stage": ["early", "growing", "long"]},
      {"id": "d348", "text": "Choose the small touches for your one-year day: a favorite dish, a meaningful spot, a few words you would like to say.", "stage": ["early", "growing", "long"]},
      {"id": "d349", "text": "Notice your posture today: tall spine, open chest, easy shoulders. Stand like someone at home in their life."},
      {"id": "d350", "text": "A full year is close. Let the hope you feel today stretch far into the years ahead.", "stage": ["early", "growing", "long"]},
      {"id": "d351", "text": "As the big day nears, keep your days simple and steady. The same small habits that carried you here will carry you on.", "stage": ["early", "growing", "long"]},
      {"id": "d352", "text": "Spend time with someone who knew you before you started living sober. Let them see who you are now.", "stage": ["early", "growing", "long"]},
      {"id": "d353", "text": "Choose one healthy treat today: a long bath, a favorite fruit, a nap, a walk at golden hour."},
      {"id": "d354", "text": "Write a few lines to the person you were on day one, telling them what this year held.", "stage": ["early", "growing", "long"]},
      {"id": "d355", "text": "Notice how much of your life is now built around health: the people, the places, the habits. You built that.", "stage": ["early", "growing", "long"]},
      {"id": "d356", "text": "Share something good from this year with one person who will celebrate with you."},
      {"id": "d357", "text": "Picture your second year as a new ring of growth on your tree. What would you love it to hold?", "stage": ["early", "growing", "long"]},
      {"id": "d358", "text": "Breathe in slowly and remember: you only ever had to live one day at a time, and you still do."},
      {"id": "d359", "text": "Take a long walk this week and let gratitude walk with you. Name a good thing at every block or bend in the trail."},
      {"id": "d360", "text": "Almost a full year. Pause, breathe, and honor every hard and good day that brought you here.", "stage": ["early", "growing", "long"]},
      {"id": "d361", "text": "Rest well tonight. Big days are best met with a rested body and a calm mind."},
      {"id": "d362", "text": "Let the people who love you know what they have meant to you this year."},
      {"id": "d363", "text": "Think about what you want your sober life to be about in the years ahead: health, people, purpose, joy. Choose one to lead with.", "stage": ["early", "growing", "long"]},
      {"id": "d364", "text": "Live today simply and fully: water, daylight, good food, movement, people, and rest. This is the life you have been building."},
      {"id": "d365", "text": "A full trip around the sun is almost complete, and the life ahead is wide open. Keep growing, one present day at a time.", "stage": ["early", "growing", "long"]}
    ],
    weekly: [
      {"id": "w01", "title": "Begin With Water", "text": "Keep a full water bottle within reach all week and refill it three times a day. Notice how your energy, sleep, and cravings shift."},
      {"id": "w02", "title": "Your Hard Hour Plan", "text": "Find the hour of the day that pulls hardest. This week, give it a new shape: a walk, a shower, a call, a cup of tea, then an early bed. Write it down and follow it every day."},
      {"id": "w03", "title": "Three Slow Breaths", "text": "Each time you walk through a doorway this week, take three slow breaths first. Small pauses build a calmer mind."},
      {"id": "w04", "title": "One Person to Text", "text": "Choose one person you can text at any hour. Tell them this week that you might, and practice by sending them one message a day."},
      {"id": "w05", "title": "Feed Your Body Well", "text": "Cook three meals from whole foods this week, with half the plate full of color. Your leaves heal faster when your body is fed well."},
      {"id": "w06", "title": "Morning Light", "text": "Step outside within an hour of waking every day this week, even for five minutes. Morning light sets your body clock and helps sleep come at night."},
      {"id": "w07", "title": "Name the Feeling", "text": "Three times a day this week, stop and name what you feel in one word. A feeling with a name is a feeling you can tend."},
      {"id": "w08", "title": "Ride the Wave", "text": "When a craving comes this week, notice where it lives in your body, breathe with it, and wait. Most cravings crest and fall within twenty minutes."},
      {"id": "w09", "title": "A Full Evening", "text": "Plan one evening this week that is good from start to finish: a meal you love, a walk, a game or a phone call, and a good night's sleep."},
      {"id": "w10", "title": "Read and Learn", "text": "Read a chapter of a recovery book or listen to someone's sober story this week. Other people's paths light up your own."},
      {"id": "w11", "title": "Move Every Day", "text": "Twenty minutes of movement each day this week: walking, lifting, swimming, or dancing in the kitchen. Movement is medicine for mood."},
      {"id": "w12", "title": "Sleep Like It Matters", "text": "Keep the same bedtime every night this week, put screens away an hour before, and keep your room cool and dark. Rest is where healing happens."},
      {"id": "w13", "title": "Find Your People", "text": "Try one new place this week with people who live sober and thrive: a SMART Recovery meeting, a sober meetup, a running or hiking group, or a class. Sit in the back if you like, and listen."},
      {"id": "w14", "title": "Gratitude at Night", "text": "Before sleep each night this week, write down three good things from the day. Gratitude trains your eyes to find what is going right."},
      {"id": "w15", "title": "Unplugged Hour", "text": "Choose one hour each evening this week and set your phone in another room. Read, walk, talk, or rest."},
      {"id": "w16", "title": "Make a Comfort Kit", "text": "Fill a small box or bag with things that help in a hard hour: tea, a favorite photo, a journal, a playlist, a list of names. Keep it close this week."},
      {"id": "w17", "title": "Clear One Space", "text": "Clear one space in your home this week: a drawer, a counter, or your car. A clear space supports a clear mind."},
      {"id": "w18", "title": "Time Among Trees", "text": "Spend at least an hour outdoors this week, among trees or near water if you can. Leave the earbuds at home and let your senses lead."},
      {"id": "w19", "title": "Practice Your Answer", "text": "Rehearse it out loud this week: “No thanks, I'm good.” Short, kind, and ready. The more you practice, the easier it comes."},
      {"id": "w20", "title": "Cold Water Reset", "text": "When stress spikes this week, splash cold water on your face or hold a cold glass for a minute. It calms your body fast."},
      {"id": "w21", "title": "One Small Repair", "text": "Choose one relationship and take one small, steady step this week: an apology, a kept promise, a kind note. Let trust grow at its own pace."},
      {"id": "w22", "title": "Roots That Hold", "text": "Ask what you are anchored in: faith, family, values, nature, or your purpose. Spend ten minutes this week with whatever holds you steady."},
      {"id": "w23", "title": "Service Week", "text": "Do one act of service this week: help a neighbor, volunteer, set up chairs at a meeting, or cook for a friend. Giving keeps us grounded."},
      {"id": "w24", "title": "Listen to Your Body", "text": "Check in with your body three times a day this week: shoulders, jaw, stomach, breath. Tension is information. Soften what you can."},
      {"id": "w25", "title": "Plan for Celebrations", "text": "Look ahead to the next birthday, holiday, or gathering. Plan your drink, your way home, your person, and your reason to be there."},
      {"id": "w26", "title": "Look Back With Kindness", "text": "Write a short letter to yourself on the day you started. Tell that person what you have learned since."},
      {"id": "w27", "title": "Joy on Purpose", "text": "Schedule one thing this week purely for joy: a hike, a concert, a new recipe, or a game with friends."},
      {"id": "w28", "title": "The Feeling Under the Craving", "text": "When a craving comes this week, ask what is under it: stress, sadness, boredom, loneliness, or celebration. Then tend that feeling directly."},
      {"id": "w29", "title": "Back to the Basics", "text": "Pick the basic that needs the most attention right now, water, food, sleep, or movement, and give it extra tending for seven days."},
      {"id": "w30", "title": "Learn Something New", "text": "Start a skill your sober life has room for now: an instrument, a language, a craft, or a class."},
      {"id": "w31", "title": "Write It Out", "text": "Write for fifteen minutes, three times this week, about what is on your heart. Writing helps the mind make sense of hard things."},
      {"id": "w32", "title": "Face to Face", "text": "Meet someone in person this week for coffee, a walk, or a meal. Real connection face to face feeds the whole person."},
      {"id": "w33", "title": "A Quiet Corner", "text": "Set up a small quiet corner this week: a chair, a plant, a window. Sit there for five minutes each day."},
      {"id": "w34", "title": "Notice Your Wins", "text": "Each evening this week, write down one thing you handled well. Small wins build a strong trunk."},
      {"id": "w35", "title": "Speak Up Early", "text": "This week, when something bothers you, say it early, calmly, and kindly, before it builds. Honest words keep your bark healthy."},
      {"id": "w36", "title": "Your Sober Circle", "text": "Write the names of five people who help you stay strong. Reach out to each one this week."},
      {"id": "w37", "title": "A Stronger Body", "text": "Try a simple strength routine twice this week: squats, wall push-ups, a short plank. A stronger body supports a steadier mind."},
      {"id": "w38", "title": "Watch for New Shapes", "text": "Old habits can try new shapes: work, food, spending, or screens. Notice one this week, and tend the feeling underneath it."},
      {"id": "w39", "title": "Making Things Right", "text": "Is there someone you would like to make things right with? Write down what you would say, and talk it over with someone you trust before you act."},
      {"id": "w40", "title": "Give Your Story", "text": "Share a piece of your journey with someone newer on the path, in whatever way fits you: a listening ear, a coffee, a message."},
      {"id": "w41", "title": "Walk and Talk", "text": "Invite someone to walk with you this week. Moving side by side makes talking easier."},
      {"id": "w42", "title": "Live Your Values", "text": "Name three values you want to live by. Each day this week, do one thing that honors one of them."},
      {"id": "w43", "title": "Sit Down to Eat", "text": "Eat at a table at least once a day this week, with your phone away. Slow meals feed your body and calm your mind."},
      {"id": "w44", "title": "Thank Your Body", "text": "Each night this week, thank your body for one thing it did for you today."},
      {"id": "w45", "title": "When the Mood Dips", "text": "Gray days can come while the brain finds its balance. If one comes this week, keep it simple: get outside, move, eat, call someone, and go to bed early. If low moods stay for weeks, talk with your doctor or a therapist."},
      {"id": "w46", "title": "Something Festive to Sip", "text": "Find two drinks you love for special moments: sparkling water with fruit, a ginger fizz, or a hot spiced tea. Keep them on hand."},
      {"id": "w47", "title": "Mind, Body, Spirit", "text": "Pick one practice for each this week: a walk for your body, writing for your mind, and a quiet minute for your spirit."},
      {"id": "w48", "title": "Ask for What You Need", "text": "Practice asking clearly this week: “Could you sit with me a minute?” or “Could we take a walk?” Asking is strength."},
      {"id": "w49", "title": "A Letter to Your Future Self", "text": "Write a letter to yourself one year from now. Tell that person what you hope they are living."},
      {"id": "w50", "title": "Honor Your Progress", "text": "Look at how far you have come, and mark it with something healthy and good: a favorite meal, a walk, people who are proud of you."},
      {"id": "w51", "title": "Every Day Is a Gift", "text": "Be intentional with the people you love this week: one meal together, one walk, or one real conversation each day."},
      {"id": "w52", "title": "Carry It Forward", "text": "Choose the one practice from this year that helped you most, and carry it with you into the next."}
    ],
    monthly: [
      {"id": "m01", "title": "Settling In", "today": "What helped you most this week?", "past": "What is one moment from this month you are proud of?", "future": "What is one thing you would like next month to hold?"},
      {"id": "m02", "title": "Your Body", "today": "How does your body feel today, from head to toe?", "past": "What changes have you noticed in your sleep, energy, or appetite since you started?", "future": "What is one way you would like to strengthen your body next month?"},
      {"id": "m03", "title": "Your People", "today": "Who could you reach out to today?", "past": "Who has stood by you, and how?", "future": "What friendship would you like to grow?"},
      {"id": "m04", "title": "Your Feelings", "today": "What feeling is closest to the surface today, and what does it need?", "past": "What feeling have you learned to sit with that once felt too big?", "future": "What feeling would you like more of in the months ahead?"},
      {"id": "m05", "title": "Rest and Rhythm", "today": "What part of your daily rhythm is working well right now?", "past": "What part of your old routine have you let go of, and what took its place?", "future": "What one habit would make next month steadier?"},
      {"id": "m06", "title": "Halfway Around", "today": "What does a good day look like for you now?", "past": "Looking back over these months, what has surprised you most?", "future": "What would you like the next six months to grow?"},
      {"id": "m07", "title": "Your Roots", "today": "What steadies you most right now?", "past": "What held you when things were hardest?", "future": "How would you like to deepen your roots?"},
      {"id": "m08", "title": "Your Joy", "today": "What brought you joy this week?", "past": "What joy has sobriety surprised you with?", "future": "What new joy would you like to try?"},
      {"id": "m09", "title": "Your Healing", "today": "What are you healing right now?", "past": "What old hurt has grown lighter?", "future": "What would you like to heal next, and who could walk with you?"},
      {"id": "m10", "title": "Your Purpose", "today": "What gives today meaning?", "past": "How has your sense of purpose changed since you started?", "future": "What do you want your sober years to make possible?"},
      {"id": "m11", "title": "Giving Back", "today": "How did you help someone this month?", "past": "Who helped you along the way, and how could you thank them?", "future": "How would you like to give back in the year ahead?"},
      {"id": "m12", "title": "A Year of Months", "today": "Who are you today?", "past": "What are you most grateful for from this year?", "future": "What is your hope for the year ahead?"}
    ],
    mantras: [
      {"id": "mt01", "text": "Today is enough."},
      {"id": "mt02", "text": "I choose clear."},
      {"id": "mt03", "text": "This feeling will pass."},
      {"id": "mt04", "text": "Breathe in calm. Breathe out tension."},
      {"id": "mt05", "text": "I deserve a clear life."},
      {"id": "mt06", "text": "One good hour, then another."},
      {"id": "mt07", "text": "My mind is clear today."},
      {"id": "mt08", "text": "I am patient with my healing."},
      {"id": "mt09", "text": "I can do hard things."},
      {"id": "mt10", "text": "Feet on the ground."},
      {"id": "mt11", "text": "I show up for myself."},
      {"id": "mt12", "text": "A craving is a wave. I ride it."},
      {"id": "mt13", "text": "I am growing roots."},
      {"id": "mt14", "text": "I choose the next right thing."},
      {"id": "mt15", "text": "Strong, steady, sober."},
      {"id": "mt16", "text": "I meet today awake."},
      {"id": "mt17", "text": "Clear mornings are mine."},
      {"id": "mt18", "text": "I reach out early."},
      {"id": "mt19", "text": "My body is healing."},
      {"id": "mt20", "text": "I am building a life I love."},
      {"id": "mt21", "text": "Present, clear, and here."},
      {"id": "mt22", "text": "Slow breath, steady heart."},
      {"id": "mt23", "text": "Every return to the path counts."},
      {"id": "mt24", "text": "I begin again today."},
      {"id": "mt25", "text": "Healing is real."},
      {"id": "mt26", "text": "I am more than my past."},
      {"id": "mt27", "text": "Today I tend my roots."},
      {"id": "mt28", "text": "Hope grows here."},
      {"id": "mt29", "text": "I choose connection."},
      {"id": "mt30", "text": "Ask, then accept the help."},
      {"id": "mt31", "text": "I protect my peace."},
      {"id": "mt32", "text": "Clear mind, full heart."},
      {"id": "mt33", "text": "Kind to myself today."},
      {"id": "mt34", "text": "I am becoming who I am."},
      {"id": "mt35", "text": "Rest is strength."},
      {"id": "mt36", "text": "I keep my promises to me."},
      {"id": "mt37", "text": "Feel it, name it, tend it."},
      {"id": "mt38", "text": "I am stronger than this hour."},
      {"id": "mt39", "text": "I decide who I become."},
      {"id": "mt40", "text": "Grounded and growing."},
      {"id": "mt41", "text": "I trust the path."},
      {"id": "mt42", "text": "I listen to my body."},
      {"id": "mt43", "text": "My sober days are mine."},
      {"id": "mt44", "text": "Gentle with myself, firm with my choice."},
      {"id": "mt45", "text": "Courage is quiet, and it is mine."},
      {"id": "mt46", "text": "One more sober sunrise."},
      {"id": "mt47", "text": "Small steps, deep roots."},
      {"id": "mt48", "text": "I belong here."},
      {"id": "mt49", "text": "I can sit with this."},
      {"id": "mt50", "text": "Peace over pressure."},
      {"id": "mt51", "text": "I am proud of me."},
      {"id": "mt52", "text": "Here, now, sober."},
      {"id": "mt53", "text": "My future self thanks me."},
      {"id": "mt54", "text": "Look how far I've come."},
      {"id": "mt55", "text": "I live sober because I'm worth it."},
      {"id": "mt56", "text": "Love the people in front of me."},
      {"id": "mt57", "text": "Steady through the storm."},
      {"id": "mt58", "text": "I tend what matters."},
      {"id": "mt59", "text": "My life is opening up."},
      {"id": "mt60", "text": "One breath. One step. One day."}
    ],
    milestones: {
      d1: {"head": "Day One", "text": "You started. That is the bravest step there is. Today, drink some water, eat something good, rest, and let one person know. We are so glad you are here."},
      d3: {"head": "Three Days", "text": "Three days of choosing yourself. Your body is already at work healing. Keep resting, keep drinking water, and keep reaching out."},
      d7: {"head": "One Week", "text": "A whole week. You have met seven mornings and seven nights, and each one showed you something about your own strength."},
      d14: {"head": "Two Weeks", "text": "Two weeks, and your sleep, your mind, and your body are finding a new rhythm. Keep tending the basics. They are working."},
      d21: {"head": "Three Weeks", "text": "Three weeks of showing up. New habits are taking root. Notice what helps you most, and lean into it."},
      m1: {"head": "One Month", "text": "A month of sober days. Look at all you have lived through with clear eyes. You are building something real."},
      m2: {"head": "Two Months", "text": "Two months. The early fog is lifting, and you are learning what steadies you. That knowledge is yours for life."},
      m3: {"head": "Three Months", "text": "Ninety days and more. This is a season of real change, and your roots are growing deeper every day."},
      m4: {"head": "Four Months", "text": "Four months. You have met hard days and good ones, and you are still growing. That is what strength looks like."},
      m5: {"head": "Five Months", "text": "Five months. Look at the people around you, the habits you have built, the mornings you have woken up clear. Your life is filling in."},
      m6: {"head": "Six Months", "text": "Half a year. Take a moment to honor how far you have come, then turn back to today, where your life is happening."},
      m7: {"head": "Seven Months", "text": "Seven months. Your sober life has its own rhythm now. Keep tending it with sleep, good food, movement, and people."},
      m8: {"head": "Eight Months", "text": "Eight months of choosing a clear mind. Somewhere along the way, you have become someone others can lean on, too."},
      m9: {"head": "Nine Months", "text": "Nine months. Something new has been growing all this time: a steadier you. Celebrate it in a healthy, joyful way."},
      m10: {"head": "Ten Months", "text": "Ten months. Think of what you know now that you wished you had known on day one. That wisdom can light the way for someone just starting."},
      m11: {"head": "Eleven Months", "text": "Eleven months. A full year is close, and every day of this one has mattered. Keep living today fully."},
      y1: {"head": "One Year", "text": "One year sober. A full trip around the sun: every season, every holiday, every hard day and every good one, met with a clear mind. This is big. Celebrate it with the people who love you, and be proud."},
      y2: {"head": "Two Years", "text": "Two years. The foundation you poured in your first year is holding a whole life now. Keep building on it."},
      y3: {"head": "Three Years", "text": "Three years. Sobriety is becoming part of who you are, a steady trunk that carries everything else."},
      y4: {"head": "Four Years", "text": "Four years. Your choices have become a way of life. Look at what has grown: health, trust, friendships, and joy."},
      y5: {"head": "Five Years", "text": "Five years. Half a decade of mornings met awake. Your life shows what is possible, and someone newer is watching with hope."},
      y6: {"head": "Six Years", "text": "Six years. The roots that first held you still hold, and they keep growing deeper. Keep tending them."},
      y7: {"head": "Seven Years", "text": "Seven years. The life you are building has depth now: stories, friendships, and wisdom you can pass on."},
      y8: {"head": "Eight Years", "text": "Eight years. Each year adds a ring to the tree, and yours show healing, strength, and steady growth."},
      y9: {"head": "Nine Years", "text": "Nine years. Living sober is simply how you live now. Keep learning, keep growing, and keep making room for wonder."},
      y10: {"head": "Ten Years", "text": "Ten years. A decade of choosing life with a clear mind. Look at the forest you have grown, and the shade it gives others."},
      y: {"head": "{n} Years", "text": "{n} years sober. A whole life is being built, one present day after another, and today is still the day that matters most. Keep growing."}
    },
    love: [
      {"id": "l01", "text": "Loving someone who drinks or uses is heavy. Your feelings make sense, and you deserve support, too."},
      {"id": "l02", "text": "Tend your own body today: water, a real meal, a walk, and rest."},
      {"id": "l03", "text": "You can love someone and set clear boundaries at the same time. Boundaries are a form of love."},
      {"id": "l04", "text": "Their choices belong to them. Your peace belongs to you."},
      {"id": "l05", "text": "Find your own people: SMART Recovery Family and Friends, a therapist, or a trusted friend who lives well."},
      {"id": "l06", "text": "Choose a calm, sober moment to talk, and keep your words simple: “I love you, and I'm worried.”"},
      {"id": "l07", "text": "Notice something they are doing well, and tell them. Encouragement opens doors."},
      {"id": "l08", "text": "Take one hour today that is just for you."},
      {"id": "l09", "text": "You can feel angry, sad, hopeful, and tired all at once. Every one of those feelings belongs."},
      {"id": "l10", "text": "People change, and families heal, one honest step at a time."},
      {"id": "l11", "text": "Set down the job of fixing. Focus on what is yours to tend: your health, your words, your peace."},
      {"id": "l12", "text": "Keep your home a safe and steady place. If you ever feel unsafe, reach for help right away."},
      {"id": "l13", "text": "Children notice more than we think. Tell them simply: it is a grown-up problem, they did nothing to cause it, and they are deeply loved."},
      {"id": "l14", "text": "Get outside today. Sunlight and fresh air steady a worried heart."},
      {"id": "l15", "text": "Write down what you are carrying. Putting it on paper makes it lighter."},
      {"id": "l16", "text": "Let them carry their own consequences. That is an act of love, too."},
      {"id": "l17", "text": "Celebrate their progress, whatever its size."},
      {"id": "l18", "text": "If they slip, meet them with steadiness: “Thank you for telling me. What do you need today?”"},
      {"id": "l19", "text": "When worry rises, breathe in for four and out for six. You can stay calm in a hard moment."},
      {"id": "l20", "text": "Your life matters, too. Keep the friendships, hobbies, and dreams that make you who you are."},
      {"id": "l21", "text": "If prayer is part of your life, hand your worry over in prayer today. Or set it down for one quiet minute."},
      {"id": "l22", "text": "Share the weight with someone who understands. Carried together, it is lighter."},
      {"id": "l23", "text": "Learn about recovery. Understanding what they face helps you respond with wisdom."},
      {"id": "l24", "text": "Keep a joyful, sober home: good food, music, games, walks, and time together."},
      {"id": "l25", "text": "Hope is welcome here. Keep it alive while you keep yourself steady."},
      {"id": "l26", "text": "If opioids are part of the picture, keep naloxone in your home and learn how to use it. Being prepared is love."},
      {"id": "l27", "text": "Rest tonight. Tomorrow's strength comes from tonight's sleep."},
      {"id": "l28", "text": "Remember who they are beneath the struggle, and hold onto that person with hope."},
      {"id": "l29", "text": "Ask yourself what you need today, and give yourself one piece of it."},
      {"id": "l30", "text": "Every day you show up with love and steady boundaries, you plant seeds of healing."}
    ]
  };
  W.pick = function (list, n) { list = W[list] || list; if (!list || !list.length) return null; n = Math.floor(Number(n) || 0); return list[((n % list.length) + list.length) % list.length]; };
  W.milestone = function (key, n) { var m = W.milestones[key] || (/^y\d+$/.test(key) ? W.milestones.y : null); if (!m) return null; n = n || String(key).replace(/\D/g, ''); return { head: m.head.replace(/\{n\}/g, n), text: m.text.replace(/\{n\}/g, n) }; };
  window.GGSoberWords = W;
})();
